INSERT INTO "story_stages" ("id", "period", "title", "content", "color", "created_at") VALUES (1, '2000 - 2017 // İLK YILLAR & GENÇLİK', 'Sumidero Kasabası ve Monterrey Lise Yılları', 'Daniel Brown 06/03/2000 tarihinde Meksika''nın Monterrey şehrinde dünyaya geldi. Çocukluğunun ilk yıllarını ve ilkokul/ortaokul eğitimini Sumidero kasabasında tamamladı. Lise eğitimi için Monterrey şehrine geçti.

Lise yıllarında içine kapanık, az arkadaşı olan bir gençti. Vaktinin çoğunu spor ve yüzmeyle geçiriyordu. Zamanla lisede Javier, Luciano ve Mateo isimli 3 sıkı dost edindi. Javier’in eski arabasıyla Meksika sokaklarında turlarken araç mekaniklerine ve sürüşe karşı ilgisini keşfetti.', 'cyan', '2000-01-01T00:00:00.000Z') ON CONFLICT ("id") DO UPDATE SET "period" = EXCLUDED."period", "title" = EXCLUDED."title", "content" = EXCLUDED."content", "color" = EXCLUDED."color", "created_at" = EXCLUDED."created_at";
--> statement-breakpoint
INSERT INTO "story_stages" ("id", "period", "title", "content", "color", "created_at") VALUES (2, 'TRAVMATİK DÖNÜM NOKTASI', 'Gece Gelen Acı Telefon ve Javier’in Kaybı', 'Gelecek hayalleri kurduğu, üniversiteye hazırlandığı dönemde ailesinin kısıtlı maddi durumu araba almasına imkan tanımıyordu. Tam hayatını düzene koymaya çalışırken bir gece geç saatte telefonu çaldı.

Arayan arkadaşı Luciano''ydu. Ağlayarak en yakın dostları Javier''in ailesiyle birlikte korkunç bir trafik kazasında hayatını kaybettiği haberini verdi. Bu gece gelen acı telefon haberi, Daniel''ın ruhunda derin izler bıraktı ve hayat boyu sürecek telefon çınlaması travmasını başlattı.', 'crimson', '2000-01-01T00:00:01.000Z') ON CONFLICT ("id") DO UPDATE SET "period" = EXCLUDED."period", "title" = EXCLUDED."title", "content" = EXCLUDED."content", "color" = EXCLUDED."color", "created_at" = EXCLUDED."created_at";
--> statement-breakpoint
INSERT INTO "story_stages" ("id", "period", "title", "content", "color", "created_at") VALUES (3, 'MADDİ DÖNÜŞÜM & İLK BAŞARI', 'Eski Evi Yenileme ve İlk Arabasını Alma', 'Kaybın ardından ayakta kalmak zorunda olan Daniel, bir işe girerek sıkı şekilde para biriktirmeye başladı. Biriktirdiği sermayeyle Monterrey''de oldukça eski ve yıpranmış bir ev satın aldı.

Kendi el emeği, uykusuz geceleri ve tadilat yeteneğiyle evi tepeden tırnağa yeniledi. Kısa süre sonra bu evi Amerikalı bir aileye aldığı fiyatın tam 2 katına satmayı başardı. Kazandığı bu parayla çocukluk hayali olan ilk arabasını alabildi.', 'amber', '2000-01-01T00:00:02.000Z') ON CONFLICT ("id") DO UPDATE SET "period" = EXCLUDED."period", "title" = EXCLUDED."title", "content" = EXCLUDED."content", "color" = EXCLUDED."color", "created_at" = EXCLUDED."created_at";
--> statement-breakpoint
INSERT INTO "story_stages" ("id", "period", "title", "content", "color", "created_at") VALUES (4, 'YENİ BİR BAŞLANGIÇ', 'Los Santos’a Tek Başına Taşınma', 'Zamanla Monterrey şehri anıları ve sınırlarıyla Daniel''a dar gelmeye başladı. Artık yeni bir çevrede, hiç kimseyi tanımadığı bir metropolde sıfırdan başlama kararı aldı.

Bin bir emekle aldığı arabasını satıp tüm sermayesini yanına alarak Los Santos şehrine doğru yola çıktı. Şimdi Los Santos''ta legal yollardan tutunmaya ve bagaj lezzetleriyle insanlara dokunmaya hazır.', 'neonGreen', '2000-01-01T00:00:03.000Z') ON CONFLICT ("id") DO UPDATE SET "period" = EXCLUDED."period", "title" = EXCLUDED."title", "content" = EXCLUDED."content", "color" = EXCLUDED."color", "created_at" = EXCLUDED."created_at";
--> statement-breakpoint
INSERT INTO "story_stages" ("id", "period", "title", "content", "color", "created_at") VALUES (5, '2026 // Los Santos ''da ilk haftalar', '2026 // Los Santos ''da ilk haftalar', 'Yeni Bir Tanışma ve Tütün Satış Teklifi: 3.11.2026 tarihinde, Javier ve Juan''la birlikte çöpçülük mesleğini icra ettikleri o sıradan günde işler beklenmedik bir yöne evrildi. Çalışma esnasında yolları, Daniel''e tütün satma üzerine cazip bir iş teklifi sunabilecek yabancı biriyle kesişti. Şehirdeki ağını genişleten ve yeni fırsatları değerlendiren Daniel, bu tarz sokak bağlantılarıyla ticari hamlelerine bir yenisini daha ekleme yolunda adım attı.', 'cyan', '2026-11-04T12:16:43.439Z') ON CONFLICT ("id") DO UPDATE SET "period" = EXCLUDED."period", "title" = EXCLUDED."title", "content" = EXCLUDED."content", "color" = EXCLUDED."color", "created_at" = EXCLUDED."created_at";
--> statement-breakpoint
INSERT INTO "story_stages" ("id", "period", "title", "content", "color", "created_at") VALUES (6, '2026 // Los Santos ''da ilk haftalar', '2026 // Los Santos ''da ilk haftalar', 'Los Santos''un sert ve koşturmacalı sokaklarına adım attığından beri Daniel Brown için çok şey değişti. Şehirde ayakları üzerinde durmaya çalışan Daniel, artık sadece hayatta kalmaya çalışmıyor; adını duyuracak adımlar atıyor, sağlam dostluklar kuruyor ve geleceğini inşa ediyor.

Sokaklardan Gelen Emek ve İlk Araç: Geçimini sağlamak için bir süredir yaptığı çöpçülük mesleğinden elde ettiği düzenli gelir, ona hem bir nefes aldırdı hem de şehirdeki ilk arabasını alabilmesini sağladı. Artık Los Santos asfaltında kendi aracıyla hareket ediyor.

Hobi ve Yetenekler: Şehrin stresinden uzaklaşmak ve sakinleşmek için öğrendiği balık tutma hobisi, artık onun için günlük rutinin huzurlu bir parçası haline geldi.

Genişleyen Sosyal Çember ve Dostluklar: Şehirde yalnız olmadığını, kurduğu sağlam bağlarla kanıtladı.', 'cyan', '2026-11-04T12:23:53.672Z') ON CONFLICT ("id") DO UPDATE SET "period" = EXCLUDED."period", "title" = EXCLUDED."title", "content" = EXCLUDED."content", "color" = EXCLUDED."color", "created_at" = EXCLUDED."created_at";
--> statement-breakpoint
INSERT INTO "contacts" ("id", "name", "status", "section", "notes", "created_at") VALUES (2, 'Luciano', 'Arkadaş', 'mexico', 'Monterrey''den çocukluk arkadaşı. Acı haberi gecenin bir yarısı telefonda veren dostu.', '2026-11-04T12:04:43.611Z') ON CONFLICT ("id") DO UPDATE SET "name" = EXCLUDED."name", "status" = EXCLUDED."status", "section" = EXCLUDED."section", "notes" = EXCLUDED."notes", "created_at" = EXCLUDED."created_at";
--> statement-breakpoint
INSERT INTO "contacts" ("id", "name", "status", "section", "notes", "created_at") VALUES (3, 'Mateo', 'Arkadaş', 'mexico', 'Monterrey''deki arkadaş grubundan. Sıkıntılı günlerinde her zaman destek oldu.', '2026-11-04T12:04:43.611Z') ON CONFLICT ("id") DO UPDATE SET "name" = EXCLUDED."name", "status" = EXCLUDED."status", "section" = EXCLUDED."section", "notes" = EXCLUDED."notes", "created_at" = EXCLUDED."created_at";
--> statement-breakpoint
INSERT INTO "contacts" ("id", "name", "status", "section", "notes", "created_at") VALUES (1, 'Javier', 'Arkadaş', 'mexico', 'En yakın lise arkadaşı. Çocukluğunda araç sevgisini aşılayan dostu (Merhum - Trafik Kazası).', '2026-11-04T12:04:43.611Z') ON CONFLICT ("id") DO UPDATE SET "name" = EXCLUDED."name", "status" = EXCLUDED."status", "section" = EXCLUDED."section", "notes" = EXCLUDED."notes", "created_at" = EXCLUDED."created_at";
--> statement-breakpoint
INSERT INTO "contacts" ("id", "name", "status", "section", "notes", "created_at") VALUES (4, 'Wade Foster', 'Arkadaş', 'los_santos', 'Şehrin hareketli kafelerinde birlikte vakit geçirdiği, yemek yiyip dertleştiği; tamamen samimiyete ve sıcak insan ilişkilerine dayanan yakın bir arkadaşlık bağı kurduğu değerli bir dosttur.', '2026-11-04T12:12:07.272Z') ON CONFLICT ("id") DO UPDATE SET "name" = EXCLUDED."name", "status" = EXCLUDED."status", "section" = EXCLUDED."section", "notes" = EXCLUDED."notes", "created_at" = EXCLUDED."created_at";
--> statement-breakpoint
INSERT INTO "contacts" ("id", "name", "status", "section", "notes", "created_at") VALUES (5, 'Tyrese Monroe', 'Ortak', 'los_santos', 'Javier''in motel arkadaşı olarak hayatına giren ve kısa sürede uyumuyla dikkat çeken Tyrese, ekibin omurgasını oluşturan isimlerden biri haline geldi. Aralarındaki güvene dayalı dostluk, şehrin getirdiği stresli anlarda bile dengede kalmalarını sağladı.', '2026-11-04T12:12:25.820Z') ON CONFLICT ("id") DO UPDATE SET "name" = EXCLUDED."name", "status" = EXCLUDED."status", "section" = EXCLUDED."section", "notes" = EXCLUDED."notes", "created_at" = EXCLUDED."created_at";
--> statement-breakpoint
INSERT INTO "contacts" ("id", "name", "status", "section", "notes", "created_at") VALUES (6, 'Javier Garcia', 'Ortak', 'los_santos', 'Sahilde akşam serinliğinde yudumlanan biralar eşliğinde başlayan tanışıklıkları, kısa sürede aralarında paranın lafının bile geçmeyeceği kadar sağlam, kardeşten öte bir bağa dönüştu. Koşu yaptığı, birlikte balık tuttuğu ve her zorlukta sırtını yaslayabildiği Javier, Daniel''in Los Santos''taki en büyük dayanağı ve en yakın yoldaşıdır.', '2026-11-04T12:12:53.696Z') ON CONFLICT ("id") DO UPDATE SET "name" = EXCLUDED."name", "status" = EXCLUDED."status", "section" = EXCLUDED."section", "notes" = EXCLUDED."notes", "created_at" = EXCLUDED."created_at";
--> statement-breakpoint
INSERT INTO "contacts" ("id", "name", "status", "section", "notes", "created_at") VALUES (7, 'Helena Marcella Romana', 'Ortak', 'los_santos', '"Sepetim Gelsin" fikrinin ilk gününden bu yana masada olan, vizyonuyla projeye taze bir soluk getiren Helena; Javier gibi aralarında menfaatin ve paranın konuşulmadığı, Daniel''in en güvendiği kurucu ortaklarından ve yakın dostlarından biridir.', '2026-11-04T12:13:18.567Z') ON CONFLICT ("id") DO UPDATE SET "name" = EXCLUDED."name", "status" = EXCLUDED."status", "section" = EXCLUDED."section", "notes" = EXCLUDED."notes", "created_at" = EXCLUDED."created_at";
--> statement-breakpoint
INSERT INTO "logs" ("id", "date", "category", "title", "content", "created_at") VALUES (1, '2026-03-01', 'Önemli Karar', 'Los Santos Garajında İlk Gece', 'Monterrey geride kaldı. Cebimdeki son birikmişle eski bir garaj alanı kiraladım. Los Santos büyük ve soğuk hissettiriyor ama pes etmeyeceğim.', '2026-11-04T12:04:43.611Z') ON CONFLICT ("id") DO UPDATE SET "date" = EXCLUDED."date", "category" = EXCLUDED."category", "title" = EXCLUDED."title", "content" = EXCLUDED."content", "created_at" = EXCLUDED."created_at";
--> statement-breakpoint
INSERT INTO "logs" ("id", "date", "category", "title", "content", "created_at") VALUES (2, '2026-03-04', 'Etkinlik Projesi', 'Çelik Mide Fikrinin Doğuşu', 'Sokakta tacoları satarken insanların ne kadar mesafeli olduğunu fark ettim. Herkesi eşit kılacak "Çelik Mide" acı yeme etkinliğini organize etme fikri kafama yattı.', '2026-11-04T12:04:43.611Z') ON CONFLICT ("id") DO UPDATE SET "date" = EXCLUDED."date", "category" = EXCLUDED."category", "title" = EXCLUDED."title", "content" = EXCLUDED."content", "created_at" = EXCLUDED."created_at";
--> statement-breakpoint
INSERT INTO "logs" ("id", "date", "category", "title", "content", "created_at") VALUES (4, '2026-10-29', 'Sokak & İş', 'Sepetim Gelsin', 'Lokasyon: Sahil Kenarı
Javier ve Helena ile akşam serinliğinde yudumladığımız biralar eşliğinde masaya yatırdığımız "Sepetim Gelsin" fikri bugün resmen hayat buldu. Aramızda paranın lafının edilmediği, saf kardeşlik ve ortak vizyona dayanan bu girişimin temellerini attık. Sadece sanal bir fikir değil, şehre soluk getirecek bir hareket başlatıyoruz.', '2026-11-04T12:15:27.493Z') ON CONFLICT ("id") DO UPDATE SET "date" = EXCLUDED."date", "category" = EXCLUDED."category", "title" = EXCLUDED."title", "content" = EXCLUDED."content", "created_at" = EXCLUDED."created_at";
--> statement-breakpoint
INSERT INTO "logs" ("id", "date", "category", "title", "content", "created_at") VALUES (3, '2026-10-29', 'Sokak & İş', 'Sepetim Gelsin', 'Javier ve Helena ile birlikte sahildeki o unutulmaz bira masasında temelleri atılan "Sepetim Gelsin" projesi, onun için sıradan bir sanal girişimden çok daha fazlası haline geldi. Yaklaşık 30 kişilik detaylı bir saha anketi, derinlemesine araştırmalar ve fiziksel mekan planlarıyla desteklenen bu ortaklık, paranın lafının edilmediği kardeşlik bağlarının ve ortak vizyonun en büyük kanıtı oldu.', '2026-11-04T12:14:53.394Z') ON CONFLICT ("id") DO UPDATE SET "date" = EXCLUDED."date", "category" = EXCLUDED."category", "title" = EXCLUDED."title", "content" = EXCLUDED."content", "created_at" = EXCLUDED."created_at";
--> statement-breakpoint
